// Claude's review tests for A30 (a push that follows a reply), A31 (errors) and A32 (streams):
// the recorder (socketFromLogs) and the file validator. agy: do not edit this file.
import { describe, expect, it } from 'vitest';
import { exportProject, parseProjectFile } from './exportFile';
import { socketFromLogs } from './socketRecord';
import { newProject, type LogEntry, type SocketMock } from './types';

const RS = '\u001e';
const ids = () => {
  let n = 0;
  return () => `id${++n}`;
};
function row(method: string, startedAt: number, part: Partial<LogEntry> = {}): LogEntry {
  return {
    id: `${method}-${startedAt}`, method, url: 'ws://app.test/hubs/shop?id=abc', status: method === 'WS' ? 101 : 0,
    responseHeaders: {}, responseBody: null, responseEncoding: 'text', truncated: false, durationMs: 0,
    badge: 'real', connectionId: 'c1', startedAt, ...part,
  };
}
const up = (t: number, body: string) => row('WS ↑', t, { requestBody: body + RS });
const down = (t: number, ...msgs: string[]) => row('WS ↓', t, { responseBody: msgs.map((m) => m + RS).join('') });
const start = [row('WS', 1000), up(1001, '{"protocol":"json","version":1}'), down(1010, '{}')];

describe('A30: a server message right after a reply becomes that reply\'s push', () => {
  it('a message sent while the call waits for its answer, as a real hub does', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Join","arguments":["g1"]}'),
      down(2005, '{"type":1,"target":"GroupMsg","arguments":["g1","joined"]}'),
      down(2010, '{"type":3,"invocationId":"0"}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.onConnect).toEqual([]);
    expect(s.replies[0]!.pushes.map((p) => [p.target, p.data, p.afterMs])).toEqual([['GroupMsg', '["g1","joined"]', 0]]);
  });

  it('messages during a second call to the same method (no reply kept) go on the timeline', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Join","arguments":["a"]}'),
      down(2010, '{"type":3,"invocationId":"0"}'),
      up(3000, '{"type":1,"invocationId":"1","target":"Join","arguments":["b"]}'),
      down(3005, '{"type":1,"target":"GroupMsg","arguments":["b","joined"]}'),
      down(3010, '{"type":3,"invocationId":"1"}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.replies.map((r) => [r.when, r.pushes.length])).toEqual([['Join', 0]]);
    expect(s.onConnect.map((p) => [p.target, p.afterMs])).toEqual([['GroupMsg', 1995]]);
  });

  it('a call that never gets an answer leaves its messages on the timeline', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Slow","arguments":[]}'),
      down(2005, '{"type":1,"target":"Tick","arguments":[]}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.onConnect.map((p) => [p.target, p.afterMs])).toEqual([['Tick', 995]]);
    expect(s.replies).toEqual([]);
  });

  it('same frame, and a later frame within 1000 ms before the next client message', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Join","arguments":["g1"]}'),
      down(2010, '{"type":3,"invocationId":"0"}', '{"type":1,"target":"GroupMsg","arguments":["g1","joined"]}'),
      down(2300, '{"type":1,"target":"Seen","arguments":[1]}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.onConnect).toEqual([]);
    expect(s.replies).toHaveLength(1);
    expect(s.replies[0]!.when).toBe('Join');
    expect(s.replies[0]!.pushes.map((p) => [p.target, p.data, p.afterMs])).toEqual([
      ['GroupMsg', '["g1","joined"]', 0],
      ['Seen', '[1]', 290],
    ]);
  });

  it('not after 1000 ms, not after the next client message, but yes while a call waits', () => {
    const s = socketFromLogs([
      ...start,
      down(1500, '{"type":1,"target":"Welcome","arguments":[]}'),
      up(2000, '{"type":1,"invocationId":"0","target":"Join","arguments":["g1"]}'),
      down(2010, '{"type":3,"invocationId":"0"}'),
      down(3100, '{"type":1,"target":"Late","arguments":[]}'),
      up(4000, '{"type":1,"invocationId":"1","target":"Other","arguments":[]}'),
      down(4005, '{"type":1,"target":"BeforeAnswer","arguments":[]}'),
      down(4010, '{"type":3,"invocationId":"1","result":5}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.onConnect.map((p) => [p.target, p.afterMs])).toEqual([['Welcome', 490], ['Late', 2090]]);
    expect(s.replies.map((r) => [r.when, r.pushes.length])).toEqual([['Join', 0], ['Other', 1]]);
    // Sent while Other waited for its answer (as a real hub's Join sends GroupMsg): Other's push, at 0 ms.
    expect(s.replies[1]!.pushes.map((p) => [p.target, p.afterMs])).toEqual([['BeforeAnswer', 0]]);
  });

  it('a push after a second completion of the same method (no reply kept) stays on the timeline', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Ping","arguments":[]}'),
      down(2010, '{"type":3,"invocationId":"0","result":1}'),
      up(2500, '{"type":1,"invocationId":"1","target":"Ping","arguments":[]}'),
      down(2510, '{"type":3,"invocationId":"1","result":2}', '{"type":1,"target":"After","arguments":[]}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.replies.map((r) => [r.when, r.result, r.pushes.length])).toEqual([['Ping', '1', 0]]);
    expect(s.onConnect.map((p) => p.target)).toEqual(['After']);
  });
});

describe('A31: an error completion becomes an error reply', () => {
  it('keeps the error text', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":1,"invocationId":"0","target":"Fail","arguments":[]}'),
      down(2010, '{"type":3,"invocationId":"0","error":"An unexpected error occurred invoking \'Fail\' on the server. HubException: nope"}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.replies).toEqual([{ id: expect.any(String), when: 'Fail', respond: 'error', result: "An unexpected error occurred invoking 'Fail' on the server. HubException: nope", pushes: [] }]);
  });
});

describe('A32: a stream becomes a stream reply', () => {
  it('collects the items in order', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":4,"invocationId":"5","target":"Counter","arguments":[3]}'),
      down(2010, '{"type":2,"invocationId":"5","item":1}'),
      down(2030, '{"type":2,"invocationId":"5","item":{"n":2}}', '{"type":2,"invocationId":"5","item":"three"}'),
      down(2050, '{"type":3,"invocationId":"5"}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.replies).toEqual([{ id: expect.any(String), when: 'Counter', respond: 'stream', result: '[1,{"n":2},"three"]', pushes: [] }]);
  });
  it('a stream that ends in an error becomes an error reply; a cancelled one is skipped', () => {
    const s = socketFromLogs([
      ...start,
      up(2000, '{"type":4,"invocationId":"5","target":"Counter","arguments":[3]}'),
      down(2010, '{"type":2,"invocationId":"5","item":1}'),
      down(2020, '{"type":3,"invocationId":"5","error":"stop"}'),
      up(3000, '{"type":4,"invocationId":"6","target":"Ticker","arguments":[]}'),
      down(3010, '{"type":2,"invocationId":"6","item":1}'),
      up(3020, '{"type":5,"invocationId":"6"}'),
    ], 'c1', 'http://app.test', ids(), 5)!;
    expect(s.replies.map((r) => [r.when, r.respond, r.result])).toEqual([['Counter', 'error', 'stop']]);
  });
});

describe('A31, A32: files carry error and stream replies', () => {
  function withReply(respond: string, result: string): string {
    const p = newProject('p', 'http://a.test');
    const sock: SocketMock = {
      id: 's', enabled: true, kind: 'signalr', urlPattern: '/hub', createdAt: 0, onConnect: [],
      replies: [{ id: 'r', when: 'X', respond: respond as 'fixed', result, pushes: [] }],
    };
    p.scenarios[0]!.sockets = [sock];
    return exportProject(p);
  }
  it('accepts error and stream, and still rejects anything else', () => {
    expect(parseProjectFile(withReply('error', 'nope')).ok).toBe(true);
    const r = parseProjectFile(withReply('stream', '[1,2]'));
    expect(r.ok && r.project.scenarios[0]!.sockets![0]!.replies[0]!.respond).toBe('stream');
    expect(parseProjectFile(withReply('sometimes', '')).ok).toBe(false);
  });
});
